/** Drop whole month partitions instead of deleting rows (Phase 18.T10). */
import type { Database } from '../types.js';

export interface DroppedPartition {
  parent: string;
  partition: string;
}

/**
 * Drop child partitions whose `_YYYY_MM` suffix is before `before`.
 * Partition names are generated by the migrations; anything else is ignored.
 */
export async function dropExpiredPartitions(
  database: Database,
  parent: string,
  before: Date,
): Promise<DroppedPartition[]> {
  const rows = await database.query<{ relname: string }>(
    `SELECT child.relname
     FROM pg_inherits
     JOIN pg_class parent ON parent.oid = pg_inherits.inhparent
     JOIN pg_class child ON child.oid = pg_inherits.inhrelid
     WHERE parent.relname = $1`,
    [parent],
  );
  const cutoff = `${before.getUTCFullYear()}_${String(before.getUTCMonth() + 1).padStart(2, '0')}`;
  const dropped: DroppedPartition[] = [];
  for (const row of rows) {
    const suffix = /_(\d{4}_\d{2})$/.exec(row.relname)?.[1];
    if (!suffix || suffix >= cutoff) continue;
    await database.query(`DROP TABLE IF EXISTS "${row.relname.replace(/"/g, '""')}"`);
    dropped.push({ parent, partition: row.relname });
  }
  return dropped;
}
